const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',alert:'<path d="M10.3 2.9 2.4 17a2 2 0 0 0 1.8 3h15.6a2 2 0 0 0 1.8-3L13.7 2.9a2 2 0 0 0-3.4 0Z"/><path d="M12 9v4"/><path d="M12 17h.01"/>',nodes:'<circle cx="5" cy="12" r="2.5"/><circle cx="19" cy="5" r="2.5"/><circle cx="19" cy="19" r="2.5"/><path d="M7.5 12h3.5a3 3 0 0 0 3-3V7.5M11 12a3 3 0 0 1 3 3v1.5"/>',checklist:'<path d="m3 6 2 2 4-4"/><path d="M11 6h10"/><path d="m3 12 2 2 4-4"/><path d="M11 12h10"/><path d="m3 18 2 2 4-4"/><path d="M11 18h10"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',pulse:'<path d="M3 12h4l2.5-7 5 14 2.5-7h4"/>',tool:'<path d="M14.7 6.3a4 4 0 0 0-5-5L12 3.6 9.5 6 7.2 3.7a4 4 0 0 0 5 5l-7.7 7.7a2.1 2.1 0 0 0 3 3l7.2-7.2"/>',chart:'<path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',chevron:'<path d="m9 18 6-6-6-6"/>',yield:'<path d="M4 19V8M10 19V4M16 19v-7M22 19H2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`}
document.querySelectorAll('[data-icon]').forEach(el=>el.outerHTML=icon(el.dataset.icon));

const issues=[
 {id:'QI-2026-0184',title:'Microcracks after lamination',sub:'550W Mono PERC · Line 03',severity:'High',line:'Line 03',owner:'Arun P.',initials:'AP',status:'In progress',age:'2h ago'},
 {id:'QI-2026-0183',title:'Junction box adhesion below spec',sub:'450W Bifacial · Line 01',severity:'Medium',line:'Line 01',owner:'Priya S.',initials:'PS',status:'Open',age:'5h ago'},
 {id:'QI-2026-0180',title:'Cell string misalignment',sub:'600W TOPCon · Line 04',severity:'High',line:'Line 04',owner:'Mohan R.',initials:'MR',status:'In progress',age:'1d ago'},
 {id:'QI-2026-0178',title:'Low insulation resistance',sub:'550W Mono PERC · Line 02',severity:'Low',line:'Line 02',owner:'Neha V.',initials:'NV',status:'Closed',age:'2d ago'},
 {id:'QI-2026-0174',title:'Backsheet bubble formation',sub:'450W Bifacial · Line 03',severity:'Medium',line:'Line 03',owner:'Arun P.',initials:'AP',status:'Open',age:'3d ago'}
];
const viewNames={dashboard:'Overview',defects:'Defects',rca:'Root cause analysis',capa:'CAPA actions',inspections:'Inspections',production:'Production',equipment:'Equipment',reports:'Reports'};

function pageHead(kicker,title,description,actions=true){return `<div class="page-head"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="period-control"><button class="select-btn">${icon('calendar')} Oct 28 – Nov 03</button><button class="select-btn">All lines ⌄</button></div>`:''}</div>`}
function kpi(label,value,foot,iconName,color,trend,trendClass='up'){return `<article class="kpi-card"><div class="kpi-top"><span>${label}</span><i class="kpi-icon ${color}">${icon(iconName)}</i></div><div class="kpi-value">${value}</div><div class="kpi-foot"><span class="trend ${trendClass}">${trend}</span>${foot}</div></article>`}
function tableRows(rows=issues){return rows.map(x=>`<tr data-issue="${x.id}"><td><div class="issue-title"><span class="mini-icon">${icon('alert')}</span><div><strong>${x.title}</strong><small>${x.id} · ${x.sub}</small></div></div></td><td><span class="tag ${x.severity.toLowerCase()}">${x.severity}</span></td><td>${x.line}</td><td><span class="tag ${x.status==='In progress'?'progressing':x.status.toLowerCase()}">${x.status}</span></td><td><div class="assignee"><span class="avatar">${x.initials}</span>${x.owner}</div></td><td>${x.age}</td></tr>`).join('')}
function issuesTable(rows=issues){return `<table class="issue-table"><thead><tr><th>Quality issue</th><th>Severity</th><th>Line</th><th>Status</th><th>Owner</th><th>Updated</th></tr></thead><tbody>${tableRows(rows)}</tbody></table>`}

function dashboard(){return `${pageHead('MANUFACTURING INTELLIGENCE','Good morning, Jeevan.','Here’s what needs your attention across Chennai Plant today.')}<section class="kpi-grid">${kpi('First pass yield','96.8%','0.6% vs last week','yield','teal','↑')}${kpi('Open quality issues','12','3 critical issues','alert','red','↑ 2','down')}${kpi('CAPA on-time rate','84%','5.2% vs last month','checklist','amber','↑')}${kpi('Cost of poor quality','₹1.84L','12.4% vs last week','chart','blue','↓','up')}</section><section class="dashboard-grid"><article class="card chart-card"><div class="card-head"><div><h3>Quality trend</h3><p>Defect rate against first pass yield</p></div><div class="chart-legend"><span><i style="background:#12a48a"></i>FPY</span><span><i style="background:#dc5a55"></i>Defect rate</span></div></div><div class="chart"><div class="chart-grid"><div class="gridline"><span>100%</span></div><div class="gridline"><span>97%</span></div><div class="gridline"><span>94%</span></div><div class="gridline"><span>91%</span></div></div><svg viewBox="0 0 700 160" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#12a48a" stop-opacity=".22"/><stop offset="1" stop-color="#12a48a" stop-opacity="0"/></linearGradient></defs><path d="M0 82 C55 76,78 60,118 66 S180 88,236 61 S320 41,355 48 S430 73,475 52 S560 29,700 35 L700 160 L0 160Z" fill="url(#area)"/><path d="M0 82 C55 76,78 60,118 66 S180 88,236 61 S320 41,355 48 S430 73,475 52 S560 29,700 35" fill="none" stroke="#12a48a" stroke-width="3" vector-effect="non-scaling-stroke"/><path d="M0 118 C60 113,82 125,125 111 S190 103,237 116 S315 104,355 111 S430 95,475 102 S560 91,700 98" fill="none" stroke="#dc5a55" stroke-width="2" stroke-dasharray="5 5" vector-effect="non-scaling-stroke"/></svg><div class="chart-labels"><span>Oct 28</span><span>Oct 29</span><span>Oct 30</span><span>Oct 31</span><span>Nov 01</span><span>Nov 02</span><span>Nov 03</span></div></div></article><article class="card"><div class="card-head"><div><h3>Line health</h3><p>Real-time quality performance</p></div><button class="text-btn">VIEW LIVE</button></div><div class="health-list"><div class="health-row"><span>Line 01 · Bifacial</span><div class="progress"><i style="width:98%"></i></div><b>98.1%</b></div><div class="health-row"><span>Line 02 · Mono PERC</span><div class="progress"><i style="width:96%"></i></div><b>96.4%</b></div><div class="health-row"><span>Line 03 · Mono PERC</span><div class="progress"><i style="width:91%;background:#e89a2f"></i></div><b>91.2%</b></div><div class="health-row"><span>Line 04 · TOPCon</span><div class="progress"><i style="width:95%"></i></div><b>95.8%</b></div><div class="health-row"><span>Line 05 · TOPCon</span><div class="progress"><i style="width:97%"></i></div><b>97.1%</b></div></div></article><article class="card list-card"><div class="card-head"><div><h3>Issues requiring attention</h3><p>Prioritized by severity, risk, and age</p></div><button class="text-btn" data-view="defects">VIEW ALL →</button></div>${issuesTable(issues.slice(0,4))}</article></section>`}

function defects(){return `${pageHead('QUALITY MANAGEMENT','Defect register','Track, investigate, and resolve every manufacturing non-conformance.',false)}<div class="section-tabs"><button class="active">All issues <b>24</b></button><button>Open <b>12</b></button><button>In investigation <b>7</b></button><button>Closed <b>5</b></button></div><div class="toolbar"><div class="filter-input">${icon('search')}<input id="defectSearch" placeholder="Search issues or batch ID"></div><button class="select-btn">Severity ⌄</button><button class="select-btn">Production line ⌄</button><button class="primary-btn" id="inlineNew">＋ New issue</button></div><article class="card">${issuesTable()}</article>`}
function rca(){return `${pageHead('GUIDED INVESTIGATION','Root cause workspace','Move from symptom to verified root cause with evidence and AI guidance.',false)}<article class="card case-banner"><span class="case-icon">${icon('alert')}</span><div><span class="eyebrow">ACTIVE CASE · QI-2026-0184</span><h2>Microcracks detected after lamination</h2><p>550W Mono PERC Panel · Batch BT-031126-C · Line 03</p></div><div class="case-meta"><div><span>Severity</span><b style="color:#c84f4a">● High</b></div><div><span>Owner</span><b>Arun Prakash</b></div><div><span>Due</span><b>Nov 05, 2026</b></div></div></article><div class="rca-layout"><article class="card workflow-card"><div class="workflow-head"><div><span class="eyebrow">5 WHYS ANALYSIS</span><h3>Trace the causal chain</h3></div><span class="step-count">5 of 5 completed</span></div><div class="why-flow"><div class="why-step" data-step="01"><label>Why did panels fail EL inspection?</label><p>Multiple cells showed microcracks after the lamination process.</p></div><div class="why-step" data-step="02"><label>Why were cells cracked after lamination?</label><p>Excessive localized pressure was applied during the lamination cycle.</p></div><div class="why-step" data-step="03"><label>Why was pressure uneven?</label><p>The laminator membrane showed inconsistent thickness near zone C.</p></div><div class="why-step" data-step="04"><label>Why was membrane wear not detected?</label><p>The preventive inspection checklist did not include thickness measurement.</p></div><div class="why-step root" data-step="05"><label>Verified root cause</label><p>Membrane thickness degradation was not controlled by the maintenance standard.</p></div></div><button class="secondary-btn" style="width:100%;margin-top:5px">＋ Add supporting evidence</button></article><div><article class="card ai-panel"><div class="ai-title"><span class="ai-orb">✦</span><div><span class="eyebrow" style="color:#56d6b9">ROOTIQ ASSIST</span><h3>Investigation signals</h3></div></div><p>Based on this defect pattern and 18 similar historical cases, verify these contributing factors.</p><div class="suggestion"><span>HIGH CONFIDENCE <b>86%</b></span><p>Laminator membrane wear or contamination around zone C.</p></div><div class="suggestion"><span>MEDIUM CONFIDENCE <b>68%</b></span><p>Pressure recipe drift between batches BT-031126-B and C.</p></div><div class="suggestion"><span>CHECK EVIDENCE <b>54%</b></span><p>Pre-existing stringer damage amplified during lamination.</p></div><p class="ai-disclaimer">AI suggestions are hypotheses, not confirmed findings. Verify with physical evidence and machine records.</p></article><article class="card action-card"><h3>Containment actions</h3><div class="action-item"><span class="check"></span><span>Quarantine batch BT-031126-C</span><small>Done</small></div><div class="action-item"><span class="check"></span><span>Inspect membrane zone C</span><small>Today</small></div><div class="action-item"><span class="check"></span><span>Run EL retest on sample</span><small>Nov 04</small></div></article></div></div>`}
function capa(){const rows=[['Replace laminator membrane','QI-2026-0184','Mohan R.','Nov 04','In progress'],['Update membrane inspection SOP','QI-2026-0184','Priya S.','Nov 06','Open'],['Retrain Line 01 j-box operators','QI-2026-0183','Arun P.','Nov 08','Open'],['Calibrate stringer vision system','QI-2026-0180','Neha V.','Nov 03','In progress']];return `${pageHead('CONTINUOUS IMPROVEMENT','Corrective & preventive actions','Own every action, verify effectiveness, and prevent recurrence.',false)}<section class="kpi-grid">${kpi('Open actions','17','Across 8 investigations','checklist','blue','')}${kpi('Due this week','7','3 due in 48 hours','clock','amber','')}${kpi('Overdue','3','Needs escalation','alert','red','↑ 1','down')}${kpi('Effectiveness rate','92%','4.1% this quarter','yield','teal','↑')}</section><article class="card"><div class="card-head"><div><h3>Action tracker</h3><p>Corrective and preventive commitments</p></div><button class="primary-btn">＋ Add action</button></div><table class="issue-table"><thead><tr><th>Action</th><th>Linked issue</th><th>Owner</th><th>Due date</th><th>Status</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${r[0]}</strong></td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td><td><span class="tag ${r[4]==='Open'?'open':'progressing'}">${r[4]}</span></td></tr>`).join('')}</tbody></table></article>`}
function inspections(){return `${pageHead('QUALITY CONTROL','Inspection hub','Standardize incoming, in-process, and final quality checks.',false)}<section class="kpi-grid">${kpi('Today’s inspections','46','31 completed','search','blue','')}${kpi('Pass rate','97.4%','1.1% above target','yield','teal','↑')}${kpi('Awaiting review','8','2 high priority','clock','amber','')}${kpi('Failed checks','3','Across 2 batches','alert','red','↓ 2','up')}</section><article class="card"><div class="card-head"><div><h3>Today’s inspection schedule</h3><p>Live quality-control work queue</p></div><button class="primary-btn">＋ New inspection</button></div><table class="issue-table"><thead><tr><th>Inspection</th><th>Batch</th><th>Stage</th><th>Inspector</th><th>Result</th></tr></thead><tbody><tr><td><strong>EL visual inspection</strong></td><td>BT-031126-C</td><td>Post-lamination</td><td>Priya S.</td><td><span class="tag high">Failed</span></td></tr><tr><td><strong>IV curve test</strong></td><td>BT-031126-D</td><td>Final QC</td><td>Arun P.</td><td><span class="tag closed">Passed</span></td></tr><tr><td><strong>Peel strength test</strong></td><td>BT-031126-E</td><td>In-process</td><td>Neha V.</td><td><span class="tag progressing">In review</span></td></tr><tr><td><strong>Incoming cell inspection</strong></td><td>RM-0311-22</td><td>Incoming</td><td>Mohan R.</td><td><span class="tag closed">Passed</span></td></tr></tbody></table></article>`}
function generic(view){const cfg={production:['PRODUCTION INTELLIGENCE','Production performance','Monitor throughput, yield, rejection, and shift performance in one place.'],equipment:['ASSET RELIABILITY','Equipment health','Connect quality events with machine conditions and maintenance history.'],reports:['ANALYTICS & REPORTING','Quality reports','Turn investigation and inspection data into decision-ready reports.']}[view];return `${pageHead(cfg[0],cfg[1],cfg[2])}<section class="kpi-grid">${kpi('Overall efficiency','88.4%','2.3% this month','pulse','teal','↑')}${kpi('Output today','4,286','of 5,000 target','chart','blue','86%')}${kpi('Unplanned downtime','42 min','18 min below average','clock','amber','↓','up')}${kpi('Quality loss','₹38,400','Estimated today','alert','red','↓ 8%','up')}</section><article class="card"><div class="empty-state"><span class="kpi-icon teal" style="margin:auto">${icon('chart')}</span><h3>${cfg[1]} module is ready</h3><p>This product area is designed for live ERP, MES, and machine-data integration.</p><button class="primary-btn" data-view="dashboard">Return to overview</button></div></article>`}

const renderers={dashboard,defects,rca,capa,inspections,production:()=>generic('production'),equipment:()=>generic('equipment'),reports:()=>generic('reports')};
let current='dashboard';
function navigate(view){current=view;document.getElementById('content').innerHTML=(renderers[view]||dashboard)();document.getElementById('pageCrumb').textContent=viewNames[view]||'Overview';document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view));closeCommand();closeSidebar();wireView();window.scrollTo({top:0,behavior:'smooth'})}
function wireView(){document.querySelectorAll('[data-view]').forEach(x=>x.onclick=()=>navigate(x.dataset.view));document.querySelectorAll('[data-issue]').forEach(x=>x.onclick=()=>navigate('rca'));const d=document.getElementById('defectSearch');if(d)d.oninput=()=>{const q=d.value.toLowerCase();document.querySelector('tbody').innerHTML=tableRows(issues.filter(x=>Object.values(x).join(' ').toLowerCase().includes(q)));wireView()};const n=document.getElementById('inlineNew');if(n)n.onclick=openIssue}
document.querySelectorAll('.nav-item,[data-view]').forEach(x=>x.addEventListener('click',()=>navigate(x.dataset.view)));
const sidebar=document.getElementById('sidebar'),scrim=document.getElementById('scrim');
function closeSidebar(){sidebar.classList.remove('open');scrim.classList.remove('open')}
document.getElementById('menuBtn').onclick=()=>{sidebar.classList.add('open');scrim.classList.add('open')};scrim.onclick=closeSidebar;
const issueModal=document.getElementById('issueModal');function openIssue(){issueModal.classList.add('open');issueModal.setAttribute('aria-hidden','false');setTimeout(()=>issueModal.querySelector('input').focus(),100)}function closeIssue(){issueModal.classList.remove('open');issueModal.setAttribute('aria-hidden','true')}
document.getElementById('newIssueBtn').onclick=openIssue;document.querySelectorAll('.close-modal').forEach(x=>x.onclick=closeIssue);issueModal.onclick=e=>{if(e.target===issueModal)closeIssue()};
document.getElementById('issueForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target);issues.unshift({id:'QI-2026-0185',title:fd.get('title'),sub:fd.get('product')+' · '+fd.get('line'),severity:fd.get('severity'),line:fd.get('line'),owner:'Jeevan K.',initials:'JK',status:'Open',age:'Just now'});closeIssue();showToast();navigate('rca');e.target.reset()};
const command=document.getElementById('command');function openCommand(){command.classList.add('open');command.setAttribute('aria-hidden','false');setTimeout(()=>document.getElementById('commandInput').focus(),50)}function closeCommand(){command.classList.remove('open');command.setAttribute('aria-hidden','true')}
document.getElementById('searchBtn').onclick=openCommand;command.onclick=e=>{if(e.target===command)closeCommand()};command.querySelectorAll('[data-view]').forEach(x=>x.onclick=()=>navigate(x.dataset.view));
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommand()}if(e.key==='Escape'){closeCommand();closeIssue()}});
function showToast(){const t=document.getElementById('toast');t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3300)}
navigate('dashboard');
